    upper=1-math.pow(.05,1/60)
    doc={"schema_version":1,"id":"semantic-protocol-v1","status":"frozen-before-run","research_question":"Does the Tacitra task capsule plus typed edit reduce total provider tokens versus Tacitra ordinary source/diff without reducing acceptance by more than five percentage points?","design":{"development_cases":6,"heldout_cases":60,"categories":{"repository-change":30,"debug-repair":30},"representations":list(RUN.REPRESENTATIONS),"repetitions":1,"trials_per_case":5,"total_trials":300,"maximum_attempts_per_trial":3,"max_repair_rounds":2,"primary":"tacitra-semantic minus tacitra-ordinary","exploratory":["tacitra-semantic minus python-ordinary","tacitra-semantic minus go-ordinary","tacitra-semantic minus rust-ordinary"],"session_condition":"stateless repeated task; cold single task is one such request; warm results are arithmetic simulations only"},"model_condition":{"provider":config["provider"],"model":config["model"],"settings":config["settings"],"request_timeout_seconds":config["request_timeout_seconds"],"max_output_characters":config["max_output_characters"],"schedule_seed":config["schedule_seed"],"substitution_allowed":False},"statistics":{"independent_unit":"case","independent_cases":60,"bootstrap_samples":20000,"bootstrap_seed":20260913,"paired_case_cluster_bootstrap":True,"noninferiority_limit":.05,"one_sided_alpha":.05,"zero_loss_exact_upper":upper,"sample_size_formula":"ceil(log(0.05)/log(0.95)) = 59; use 60","primary_metric":"total provider tokens per accepted solution, all failed attempts retained in numerator"},"decision_rule":{"supports_semantic_protocol":"primary one-sided bootstrap token upper < 0, exact acceptance-loss upper <= 0.05, and semantic acceptance in every category","does_not_support_semantic_protocol":"primary one-sided bootstrap token lower >= 0 or observed semantic loss rate > 0.05","inconclusive":"otherwise"},"repair":{"ordinary":"previous artifact plus bounded first validation failure","semantic":"minimal repair-context-v1 only; no repeated capsule, specification, or successful operations"},"ablations":{"measured_locally":["task-scoped-specification","semantic-query","typed-structural-patch"],"repair_context":"observable only on failed model attempts","conversation_or_cache":"stateless primary; warm 1/10/100 arithmetic simulation; cached tokens recorded but never subtracted"},"budget":{"evidence":"estimated","calibration":"cross-language-v1 provider-token per UTF-8-byte medians","estimated_first_attempt_provider_tokens":estimated,"expected_api_calls_if_no_repairs":300,"maximum_api_calls":900,"projected_tokens_if_every_attempt_matches_first_attempt_size":estimated*3,"projection_is_not_a_hard_ceiling":True,"estimated_cost_usd":None,"cost_note":"No public price is available for the exact pinned model; apply account input/output rates to measured usage before execution."},"fairness":{"new_heldout_cases":True,"reference_artifacts_excluded_from_prompts":True,"same_task_and_acceptance_across_five_representations":True,"seeded_interleaving":True,"semantic_task_not_duplicated_outside_capsule":True,"failed_trials_retained":True},"pins":RUN.pins(config,cases)}
